// Close is to release resource of ConnPool, it is executed when client is closed.
func (p *connPool) Close() error {
	p.conns.Range(func(addr, trans interface{}) bool {
		p.conns.Delete(addr)
		trans.(*transports).close()
		return true
	})
	return nil
}

// Dump returns diagnostic information about the connection pool state.
// It provides visibility into active connections, their health status, and pool utilization.
func (p *connPool) Dump() interface{} {
	type ConnInfo struct {
		Address       string
		PoolSize      uint32
		ActiveConns   int
		Index         uint32
		RemoteService string
	}

	var infos []ConnInfo
	p.conns.Range(func(key, value interface{}) bool {
		addr := key.(string)
		trans := value.(*transports)

		activeCount := 0
		for i := 0; i < int(trans.size); i++ {
			if trans.cliTransports[i] != nil {
				if trans.cliTransports[i].(grpc.IsActive).IsActive() {
					activeCount++
				}
			}
		}

		infos = append(infos, ConnInfo{
			Address:       addr,
			PoolSize:      trans.size,
			ActiveConns:   activeCount,
			Index:         atomic.LoadUint32(&trans.index),
			RemoteService: p.remoteService,
		})
		return true
	})

	return map[string]interface{}{
		"pool_type":      "grpc_conn_pool",
		"remote_service": p.remoteService,
		"configured_size": p.size,
		"addresses":      infos,
	}
}

